    if (!file.is_open()) { // Vérifier si le fichier a pu être ouvert
        std::cerr << "Erreur : impossible d'ouvrir le fichier." << std::endl;
        return 1;
    }

    while (std::getline(file, line)) { // Lire chaque ligne du fichier
        size_t pos = 0; // Position initiale pour la recherche
        while ((pos = line.find(word, pos)) != std::string::npos) { // Rechercher le mot dans la ligne
            count++; // Augmenter le compteur de occurrences
            pos++; // Passer à la position suivante pour ne pas compter plusieurs fois le même mot
        }
    }

    file.close(); // Fermer le fichier

    std::cout << "Le mot \"" << word << "\" apparait " << count << " fois dans le fichier." << std::endl;

    return 0;
}
